// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address logger1, address logger2) public {
        vm.assume(logger1 != address(0) && logger2 != address(0));
        vm.assume(logger1 != logger2);

        vm.prank(address(0));
        c.setApprovedLogger(logger1, true);
        vm.prank(address(0));
        c.setApprovedLogger(logger2, false);

        assertTrue(c.approvedLoggers(logger1) != c.approvedLoggers(logger2));
    }
}
